Answer.ValidationCode:
$ErrorActionPreference = 'Stop'
try {
    foreach ($op in @('is-enabled','is-active')) {
        $state = @(& systemctl $op chronyd.service 2>&1)
        if ($LASTEXITCODE -ne 0) { throw "chronyd $op failed" }
    }
    $lines = @(Get-Content -LiteralPath '/etc/chrony.conf' | Where-Object { $_ -match '^\s*(server|pool|peer)\s+' })
    if ($lines.Count -eq 0) { throw 'No configured time sources' }
    foreach ($line in $lines) {
        if ($line -notmatch '\bmaxpoll\s+([0-9]+)(?:\s|$)' -or [int]$Matches[1] -gt 16) { throw 'Missing or excessive maxpoll' }
    }
    $tracking = @(& chronyc tracking 2>&1)
    if ($LASTEXITCODE -ne 0 -or ($tracking -join "`n") -notmatch 'Leap status\s*:\s*Normal') { throw 'Chrony is not synchronized' }
    return @{ Valid = $true; Results = "Chrony enabled/active, maxpoll <=16 and synchronized. Configured sources: $($lines -join '; '). Source authority is a manual security-plan determination, not established by synchronization." }
} catch { return @{ Valid = $false; Results = $_.Exception.Message } }
